import {store,uid,date,newProject,chapter,card,take,ordered,chapterCards,position,sourceCard,visual,tags,tagDefs,ratio,reuseFamily,completionOf,setFamilyCompletion,allCards,gridPreset} from './state.js';
import {assetUrl,attachImages,importImageFiles,importProject,exportProject,saveBlob,chooseExportDirectory,drawVisual,safe} from './media.js';
const $=(sel,root=document)=>root.querySelector(sel), $$=(sel,root=document)=>[...root.querySelectorAll(sel)];
const app=$('#app'), files=$('#files');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const icon={new:'＋',folder:'▱',menu:'☰',sticky:'▤',print:'▧',tag:'◇',settings:'⚙',back:'‹',edit:'✎',archive:'▤'};
const UI={screen:'browser',browserFilter:'all',folderId:'root',selectedBrowser:[],focusBrowser:0,sort:'modified',search:'',modal:null,menu:false,chapterId:null,left:true,right:true,bucket:'unassigned',archiveKind:'cards',lostScope:'chapter',rightMode:'holding',selected:[],bucketSelected:[],selectionZone:'main',quick:false,print:{orientation:'portrait',cols:3,rows:5,spacing:1,scale:1,notes:false,tags:true,numbers:true,stickers:true,chapterTitle:true,projectTitle:true,range:true,pageNum:true,blankWhite:true,noteFont:12,dpi:200},filterTag:'all',highlightTag:'none',highlightIndex:0,performIdx:0,performChapter:'all',takeId:null,playing:false,recording:false,performTime:0,performZoom:1,performWaveHeight:56,boardPages:{},showStickies:false,completionChapterId:null,completionSelected:[],completionThumb:220,contextTagId:null,contextEl:null,drag:null,dragChapter:null,editFocus:false,focusIndex:0,theme:store.state.settings.theme,autoJump:false};
let activeAudio=null,audioUrl=null,performRAF=0,performanceStart=0,renderToken=0,dragEl=null,toastTimer,sfxContext=null,lastWaveDraw=0;
let exportedView='storyboard';
const p=()=>store.project, chapters=()=>p()?.chapters.filter(c=>!c.unused)||[], activeCh=()=>p()?.chapters.find(c=>c.id===UI.chapterId)||chapters()[0], activeCards=()=>p()?chapterCards(p(),activeCh()?.id):[];
const activeTake=()=>p()?.perform.takes.find(t=>t.id===(UI.takeId||p().perform.activeTakeId))||p()?.perform.takes[0];
const item=(id)=>p()?[...p().stories,...p().unassigned,...p().lost,...p().archived,...store.state.globalAssets].find(x=>x.id===id):null;
const color=(t)=>p()?.customTags?.find(x=>x.id===t)?.color||tagDefs[t]?.color||'#95b6d7';
const label=(t)=>p()?.customTags?.find(x=>x.id===t)?.name||tagDefs[t]?.name||t;
const symbol=(t)=>p()?.customTags?.find(x=>x.id===t)?.icon||tagDefs[t]?.icon||'◆';
const copyTitle=s=>{if(!s.reuseOf)return '';const origin=allCards(p()).find(x=>x.id===s.reuseOf);const copies=allCards(p()).filter(x=>x.reuseOf===s.reuseOf).sort((a,b)=>(Number(a.reuseIndex)||Infinity)-(Number(b.reuseIndex)||Infinity));const n=copies.findIndex(x=>x.id===s.id)+1;return `copy${n>1?' '+n:''} of ${origin?position(p(),origin.id):'archived card'}`;};
const globalCount=c=>{const orderedCh=chapters();let n=0;for(const x of orderedCh){if(x.id===c.id)break;n+=chapterCards(p(),x.id).length;}return n;};
const cjClickSounds=[1,2,3].map(i=>{const a=new Audio(`assets/menu-click-${i}.wav`);a.preload='auto';return a;});
const cjPageSounds={forward:new Audio('assets/page-flip-forward.wav'),back:new Audio('assets/page-flip-back.wav')};
for(const a of Object.values(cjPageSounds))a.preload='auto';
let cjClickIndex=0;
function playOriginal(a){if(!store.state.settings.sfx)return;try{const sound=a.cloneNode(true);sound.volume=Math.min(1,Math.max(0,Number(store.state.settings.sfxVolume??.4)));const playback=sound.play();playback?.catch?.(()=>{});}catch(e){console.warn('UI sound failed',e);}}
function uiSound(){playOriginal(cjClickSounds[cjClickIndex++%cjClickSounds.length]);}
function pageSound(direction='forward'){playOriginal(cjPageSounds[direction]||cjPageSounds.forward);}

function toast(txt){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.textContent=txt;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),2400);}
function change(label,fn,{render:shouldRender=true}={}){store.change(label,fn);if(shouldRender)render();}
function render(){const scrollPos={};for(const id of ['paper-list','.print-center','.completion-content','.completion-chapter-list']){const node=$(id.startsWith('.')?id:'#'+id);if(node)scrollPos[id]=node.scrollTop;}renderToken++;document.body.style.setProperty('--note-font',(store.state.settings.noteSize||14)+'px');document.body.style.setProperty('--letterbox',store.state.settings.letterbox==='white'?'#fff':'#000');document.body.className=`theme-${UI.theme} page-${UI.screen}${store.state.settings.animations?'':' animations-off'}`;document.body.style.setProperty('--theme-tint',UI.screen==='perform'?'#193365':UI.screen==='print'?'#d48ab8':UI.screen==='completion'?'#73b89a':UI.screen==='browser'?'#8886cd':'#bc7880');
 if(UI.screen==='browser')app.innerHTML=browserHtml();
 else if(UI.screen==='storyboard')app.innerHTML=storyboardHtml();
 else if(UI.screen==='print')app.innerHTML=printHtml();
 else if(UI.screen==='perform')app.innerHTML=performHtml();
 else if(UI.screen==='completion')app.innerHTML=completionHtml();
 if(UI.modal)renderModal(); if(UI.menu)renderMenu();attachImages(app);if(UI.screen==='perform'){setupAudio();drawWave();refreshPerform();}if(UI.screen==='storyboard'){fitStoryboardPage();refreshHighlights();}for(const [id,top] of Object.entries(scrollPos)){const node=$(id.startsWith('.')?id:'#'+id);if(node)node.scrollTop=top;}}
function heading(){return `<div class="brand" data-act="browser" title="Save and return to projects"><span class="brand-emblem">✧</span><span>Storyboard Studio</span></div>`;}
function toolbar(){return `<header class="topbar">${heading()}<span class="project-head">${esc(p()?.name||'')}</span><div class="top-actions">${UI.screen==='storyboard'?`<button data-act="completion" class="completion-corner" title="Completion">✓ Completion</button>`:UI.screen==='perform'?`<button data-act="storyboard" class="mode-link">← Storyboard</button><span class="current-mode">Perform</span><button data-act="edit-soon" class="mode-link">Edit · Soon</button>`:''}${UI.screen==='completion'?`<label class="completion-size-control top-size" title="Completion thumbnail size">Thumbnail size <input data-completion-size type="range" min="120" max="350" step="10" value="${UI.completionThumb}"></label>`:''}<button data-act="menu" title="Open menu (Tab)" class="icon-button menu-button">☰</button></div></header>`;}
function folderIcon(f){return `<div class="folder-art"><img src="assets/folder-icon.png" style="filter:hue-rotate(${((Number(f.hue)||350)-350)}deg)" alt=""></div>`;}
function browserItems(){const root=UI.folderId==='root',q=UI.search.trim().toLowerCase();let folders=store.state.folders.filter(f=>f.id!=='root'&&f.parentId===(root?'root':UI.folderId)),projects=store.state.projects.filter(x=>x.folderId===UI.folderId||root&&UI.browserFilter==='all'&&x.folderId==='root');
 if(UI.browserFilter==='folders')projects=[];if(['videos','shorts'].includes(UI.browserFilter)){folders=[];projects=store.state.projects.filter(x=>UI.browserFilter==='shorts'?x.ratio==='9:16':x.ratio!=='9:16');if(!root)projects=projects.filter(x=>x.folderId===UI.folderId);}
 if(q){folders=folders.filter(f=>f.name.toLowerCase().includes(q));projects=projects.filter(x=>x.name.toLowerCase().includes(q));}
 const sorter=(a,b)=>Number(!!b.pinned)-Number(!!a.pinned)|| (UI.sort==='name'?a.name.localeCompare(b.name):UI.sort==='created'?new Date(b.createdAt||0)-new Date(a.createdAt||0):UI.sort==='completion'?Number(b.completion||0)-Number(a.completion||0):new Date(b.modifiedAt||0)-new Date(a.modifiedAt||0));
 return [{type:'new',id:'new'},...folders.sort(sorter).map(f=>({type:'folder',id:f.id,data:f})),...projects.sort(sorter).map(x=>({type:'project',id:x.id,data:x}))];}
function selectedProjectIds(){return UI.selectedBrowser.filter(id=>store.state.projects.some(project=>project.id===id));}
function browserMoveBar(){const ids=selectedProjectIds();if(!ids.length)return '';const folders=store.state.folders.filter(f=>f.id!=='root');return `<div class="browser-move-bar" role="group" aria-label="Move selected projects"><strong>${ids.length} selected</strong><select id="browser-move-destination" aria-label="Destination folder"><option value="root">All Projects</option>${folders.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select><button data-act="browser-move-selected" title="Move the selected projects">Move to folder</button><button data-act="browser-create-for-selected" title="Create a folder containing the selected projects">＋ New folder</button><button data-act="browser-clear-selection" title="Clear selection">✕</button></div>`;}
function refreshBrowserSelection(){ $$('.browser-tile[data-kind="project"]').forEach(el=>el.classList.toggle('multi-selected',UI.selectedBrowser.includes(el.dataset.browse)));}
function stickers(xs){return (xs||[]).slice(0,2).map(s=>`<span class="browser-sticker ${esc(s)}">${s==='star'?'★':s==='heart'?'♥':'✓'}</span>`).join('');}
function browserDetails(project){if(!store.state.settings.browserInfo)return '';const active=project.chapters.filter(c=>!c.unused);const all=active.flatMap(c=>(project.stories||[]).filter(s=>s.chapterId===c.id));const percent=all.length?Math.round(all.reduce((sum,s)=>sum+(s.completionStatus==='green'?1:s.completionStatus==='yellow'?.5:0),0)*100/all.length):0;const stamp=t=>t?new Date(t).toLocaleString(): '—';return `<div class="browser-details"><span>Created: ${esc(stamp(project.createdAt))}</span><span>Modified: ${esc(stamp(project.modifiedAt))}</span><span>Completion: ${percent}%</span></div>`;}
function pinIcon(){return `<svg class="pin-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 3h6l-1 6 3 3v2H7v-2l3-3-1-6Z"/><path d="M12 14v7"/></svg>`;}
function folderNewIcon(){return `<svg class="folder-add-svg" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="M5 13a4 4 0 0 1 4-4h10l4 4h15a4 4 0 0 1 4 4v20a4 4 0 0 1-4 4H9a4 4 0 0 1-4-4V13Z" fill="#aac4ec" stroke="#6088be" stroke-width="2"/><path d="M6 22h35l-5 17H10a4 4 0 0 1-4-4V22Z" fill="#86a8d6" stroke="#6088be" stroke-width="1.6"/><circle cx="36" cy="35" r="9" fill="#f7faff" stroke="#6a90c4" stroke-width="2"/><path d="M36 30v10m-5-5h10" stroke="#587fbb" stroke-width="2.4" stroke-linecap="round"/></svg>`;}
function browserHtml(){const xs=browserItems(),folder=store.state.folders.find(f=>f.id===UI.folderId),inside=UI.folderId!=='root',hue=Number(folder?.hue??230);
 return `<div class="browser-shell" style="--folder-hue:${hue}"><header class="browser-top"><div class="browser-wordmark">✧ <span>Storyboard Studio</span><small>NEXT 0.3.11</small></div><div class="browser-tools"><button data-act="browser-settings" title="Settings">⚙</button><button data-act="browser-info" title="Project information" aria-pressed="${!!store.state.settings.browserInfo}" class="browser-info-toggle ${store.state.settings.browserInfo?'active':''}">ⓘ</button></div></header>
 <div class="browser-panel ${inside?'inside-folder':''}"><div class="browser-filters"><div class="browser-filter-row">${['all','folders','videos','shorts'].map(v=>`<button data-filter="${v}" class="browser-filter ${UI.browserFilter===v?'active':''}" aria-pressed="${UI.browserFilter===v}">${v==='all'?'All Projects':v[0].toUpperCase()+v.slice(1)}</button>`).join('')}<button data-act="folder-new" class="folder-create-button" title="Create folder">${folderNewIcon()}</button></div><div class="browser-filter-row"><select data-act="sort" aria-label="Sort projects"><option value="modified" ${UI.sort==='modified'?'selected':''}>Recently Modified</option><option value="name" ${UI.sort==='name'?'selected':''}>Name A–Z</option><option value="created" ${UI.sort==='created'?'selected':''}>Date Created</option><option value="completion" ${UI.sort==='completion'?'selected':''}>Completion</option></select><input data-act="search" placeholder="Search projects…" value="${esc(UI.search)}"></div></div>
 ${inside?`<button class="breadcrumb" data-act="folder-back">‹ All Projects / ${esc(folder?.name||'')}</button>`:''}
 ${browserMoveBar()}<div class="project-grid lasso-surface" id="browser-grid">${xs.map((x,i)=>x.type==='new'?`<button class="browser-tile project-new ${UI.focusBrowser===i?'kbd-selected':''}" data-browse="new"><div class="tile-art new-art">＋</div><strong>New Project</strong></button>`:x.type==='folder'?`<div class="browser-tile ${UI.focusBrowser===i?'kbd-selected':''}" draggable="true" data-browse="${x.id}" data-kind="folder" title="${esc(x.data.name)}"><div class="tile-art folder-tile">${folderIcon(x.data)}${stickers(x.data.stickers)}</div><strong>${esc(x.data.name)}</strong><small>${store.state.projects.filter(p=>p.folderId===x.id).length} projects</small>${x.data.pinned?`<span class="pinned" title="Pinned">${pinIcon()}</span>`:''}</div>`:`<div class="browser-tile ${UI.focusBrowser===i?'kbd-selected':''} ${UI.selectedBrowser.includes(x.id)?'multi-selected':''}" draggable="true" data-browse="${x.id}" data-kind="project" title="${esc(x.data.name)}"><div class="tile-art"><div class="project-art" style="aspect-ratio:${ratio(x.data)}">${x.data.thumbnailId?`<img data-asset="${x.data.thumbnailId}" alt="">`:x.data.thumbnail?`<img src="${x.data.thumbnail}" alt="">`:`<svg class="project-symbol" viewBox="0 0 96 54" aria-hidden="true"><rect x="2" y="3" width="92" height="48" rx="5" fill="none" stroke="currentColor" stroke-width="3"/><path d="M9 38 31 20 44 30 61 15 87 41" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="73" cy="15" r="6" fill="currentColor"/></svg>`}</div>${stickers(x.data.stickers)}</div><strong>${esc(x.data.name)}</strong>${browserDetails(x.data)}${x.data.pinned?`<span class="pinned" title="Pinned">${pinIcon()}</span>`:''}</div>`).join('')}</div>
 </div><footer class="browser-footer"><div><button data-act="project-import">↓ Import Project</button><button data-act="export-selected">↑ Export Project</button></div><button class="primary" data-act="project-new">＋ New Project</button></footer></div>`;}

function chapterNumber(c){const roots=chapters().filter(x=>!x.parentId);if(c.parentId){const r=roots.findIndex(x=>x.id===c.parentId)+1,child=chapters().filter(x=>x.parentId===c.parentId).findIndex(x=>x.id===c.id)+1;return `${r}.${child}`;}return String(roots.findIndex(x=>x.id===c.id)+1);}
function chapterMeta(c){const n=chapterCards(p(),c.id).length;if(store.state.settings.chapterInfo==='hidden')return'';if(store.state.settings.chapterInfo==='count')return `${n}`;const base=globalCount(c);return n?`${base+1}–${base+n}`:'–';}
function chapterIsDone(c){const cards=chapterCards(p(),c.id);return cards.length>0&&cards.every(s=>s.completionStatus==='green');}
function chapterHtml(c){return `<div class="chapter-row ${c.id===UI.chapterId?'on':''} ${c.parentId?'subchapter':''} ${chapterIsDone(c)?'chapter-done':''}" data-chapter="${c.id}" draggable="true" title="${esc(c.name)}"><button class="chapter-name" data-activate-chapter="${c.id}">${chapterIsDone(c)?'<span class="chapter-check">✓</span>':''}<span class="chapter-number">${chapterNumber(c)}</span><span class="chapter-label">${esc(c.name)}</span></button><small>${chapterMeta(c)}</small></div>`;}
function chapterSidebar({print=false}={}){return `<aside class="chapter-sidebar"><div class="side-head"><strong>Chapters</strong><div>${print?'':`<button data-act="add-chapter" title="Add chapter">＋</button>`}<button data-act="toggle-chapters" title="Hide chapters">≡</button></div></div><div id="chapter-list" class="chapter-list">${chapters().map(chapterHtml).join('')}</div>${!print?'<div class="chapter-promote-target" data-drop-promote title="Drop here to make a main chapter">↖ Move to main chapters</div>':''}${!print?`<button class="sidebar-completion-button" data-act="completion" title="Open Completion">✓ Completion</button><div class="unused-zone ${p()?.chapters.some(c=>c.unused)?'has-unused':''}" data-drop-unused>${p()?.chapters.some(c=>c.unused)?`<div class="section-line">UNUSED</div>${p().chapters.filter(c=>c.unused).map(c=>`<div class="chapter-row unused" data-chapter="${c.id}" draggable="true">${esc(c.name)}</div>`).join('')}`:'<span>Drag a chapter here to keep it unused</span>'}</div>`:''}</aside>`;}
function imageHtml(s,{small=false}={}){const v=visual(p(),s);return v.blank?'<div class="blank-art">BLANK</div>':`<img data-asset="${v.variant?.assetId||''}" draggable="false" alt="">`;}
function badge(t){return `<span class="tag-badge" style="--tag:${color(t)}" title="${esc(label(t))}">${esc(symbol(t))}</span>`;}
function cardsInChapter(){let a=activeCards();if(UI.filterTag!=='all')a=a.filter(s=>tags(p(),s).includes(UI.filterTag));return a;}
function cardHtml(s,idx,{bucket=false}={}){const v=visual(p(),s),num=position(p(),s.id,store.state.settings.numbering),selected=(bucket?UI.bucketSelected:UI.selected).includes(s.id),mainNumber=typeof num==='number'&&num>0?num:'';
 return `<div class="story-entry ${selected?'selected':''} ${bucket?'bucket-card':''}" draggable="true" data-card="${s.id}" ${bucket?'data-in-bucket="1"':''}><div class="story-frame" style="aspect-ratio:${ratio(p())}">${imageHtml(s)}<div class="corner-tags">${tags(p(),s).slice(0,4).map(badge).join('')}</div><button class="tag-add" title="Add a tag" data-act="add-card-tag" data-id="${s.id}">＋</button></div><div class="story-meta">${!bucket&&store.state.settings.cardNumbers?`<span>${mainNumber||'·'}</span>`:''}${v.count>1?`<span>${String.fromCharCode(65+v.index)} (${v.count})</span>`:''}${s.reuseOf?`<span class="copy-label">${esc(copyTitle(s))}</span>`:''}</div>${!bucket&&p()?.viewPrefs.cardNotesVisible?`<textarea class="card-note inline-card-note" data-note="${s.id}" rows="3" placeholder="Add a note…" aria-label="Storyboard note">${esc(s.note||'')}</textarea>`:''}</div>`;}
function stickyHtml(n){const projectScope=!n.chapterId;return `<div class="sticky-item ${projectScope?'project-sticky':'chapter-sticky'}" data-sticky="${n.id}" style="--paper:${projectScope?'#d6eefb':'#fff0b9'}"><div class="sticky-head"><div class="sticky-scope" aria-label="Sticky note scope"><button data-sticky-scope="project" data-id="${n.id}" class="${projectScope?'selected':''}" title="Show on every chapter">Project</button><span> | </span><button data-sticky-scope="chapter" data-id="${n.id}" class="${projectScope?'':'selected'}" title="Show only on this chapter">Chapter</button></div><button title="Archive sticky" data-act="archive-sticky" data-id="${n.id}">×</button></div><textarea data-sticky-note="${n.id}" placeholder="An idea to remember…">${esc(n.text||'')}</textarea></div>`;}
function rightSidebar(){const mode=UI.rightMode,kind=UI.bucket;const source=mode==='assets'?store.state.globalAssets:(kind==='unassigned'?p().unassigned:kind==='lost'?p().lost:kind==='archived'?UI.archiveKind==='stickies'?[]:p().archived:[]);
 return `<aside class="holding-sidebar"><div class="side-head"><div class="switch-head"><button class="${mode==='holding'?'active':''}" data-act="panel-holding">Holding Area</button><button class="${mode==='assets'?'active':''}" data-act="panel-assets">Assets</button></div><button title="Hide panel" data-act="toggle-holding">≡</button></div>${mode==='holding'?`<div class="holding-tabs">${['unassigned','lost','archived'].map(v=>`<button class="${kind===v?'active':''}" data-bucket="${v}">${v==='unassigned'?'Not Assigned':v==='archived'?'Archive':'Lost'}</button>`).join('')}</div>${kind==='lost'?`<div class="mini-switch"><button data-act="lost-scope" class="${UI.lostScope==='chapter'?'active':''}" data-scope="chapter">Chapter</button><button data-act="lost-scope" class="${UI.lostScope==='project'?'active':''}" data-scope="project">Project</button></div>`:''}${kind==='archived'?`<div class="mini-switch"><button class="${UI.archiveKind==='cards'?'active':''}" data-act="archive-kind" data-kind="cards">Cards</button><button class="${UI.archiveKind==='stickies'?'active':''}" data-act="archive-kind" data-kind="stickies">Stickies</button></div>`:''}`:`<p class="muted">Shared reusable images across projects</p>`}<div class="bucket-grid lasso-surface" id="holding-grid" data-drop-bucket="${mode==='assets'?'assets':kind}">${mode==='holding'&&kind==='archived'&&UI.archiveKind==='stickies'?(p().archivedStickies||[]).map(n=>`<div class="archived-sticky"><p>${esc(n.text)}</p><div class="archive-sticky-actions"><button data-act="restore-sticky" data-id="${n.id}">Restore</button><button class="delete-sticky" data-act="delete-archived-sticky" data-id="${n.id}" title="Permanently delete archived sticky">Delete</button></div></div>`).join(''):source.filter(s=>kind!=='lost'||(UI.lostScope==='project'?s.lostScope==='project':s.lostScope!=='project'&&s.chapterId===UI.chapterId)).map(s=>cardHtml(s,0,{bucket:true})).join('')}</div><button class="drop-import" data-act="import-image" title="Import into ${mode}">＋ Import</button></aside>`;}
function boardDimensions(){const format=p()?.ratio||'16:9',base=gridPreset(store.state.settings,format),v=p()?.viewPrefs||{};return {cols:Math.max(1,Math.min(6,Number(v.gridCols||(p()?.ratio==='9:16'?4:p()?.ratio?3:base.cols)))),rows:Math.max(1,Math.min(7,Number(v.gridRows||(p()?.ratio==='9:16'?3:p()?.ratio?4:base.rows))))};}
function boardRows(){const d=boardDimensions();return p()?.viewPrefs?.cardNotesVisible?Math.max(1,Math.ceil(d.rows/2)):d.rows;}
function boardPageSize(){return boardDimensions().cols*boardRows();}
function boardPage(){const id=UI.chapterId||'';const max=Math.max(0,Math.ceil(cardsInChapter().length/boardPageSize())-1);UI.boardPages[id]=Math.max(0,Math.min(max,Number(UI.boardPages[id]||0)));return UI.boardPages[id];}
function setBoardPage(n){const id=UI.chapterId||'';const max=Math.max(0,Math.ceil(cardsInChapter().length/boardPageSize())-1);const next=Math.max(0,Math.min(max,n));if(next!==boardPage())pageSound(next>boardPage()?'forward':'back');UI.boardPages[id]=next;render();}
function revealCardPage(id){const index=cardsInChapter().findIndex(x=>x.id===id);if(index>=0)UI.boardPages[UI.chapterId]=Math.floor(index/boardPageSize());}
function boardSlots(list,offset){const slots=[];for(let i=0;i<boardPageSize();i++){const s=list[offset+i],index=offset+i;slots.push(s?`<div class="grid-item board-slot" data-slot="${index}"><button type="button" class="gap-target" data-insert="${index}" title="Insert blank before this card">＋</button>${cardHtml(s,index)}</div>`:i===list.length-offset?`<div class="grid-item board-slot board-empty" data-slot="${index}"><button class="page-add-blank" data-insert="${index}" aria-label="Add storyboard here" title="Add blank storyboard">＋</button></div>`:`<div class="grid-item board-slot board-empty" data-slot="${index}"></div>`);}return slots.join('');}
function storyboardHtml(){const C=cardsInChapter(),show=p()?.viewPrefs.cardNotesVisible,page=boardPage(),pages=Math.max(1,Math.ceil(C.length/boardPageSize())),offset=page*boardPageSize();return `${toolbar()}<div class="workspace-shell ${UI.left?'':'no-left'} ${UI.right?'':'no-right'}">${UI.left?chapterSidebar():`<button class="rail-open left" data-act="toggle-chapters" title="Show chapters">≡</button>`}<main class="board-main"><div class="board-minihead"><div><h2>${esc(activeCh()?.name||'Chapter')}</h2></div><div class="board-icons"><button data-act="toggle-notes" class="notes-tool ${show?'on':''}" title="Show/hide card notes"><img src="assets/notes-icon.png" alt=""></button><button data-act="toggle-stickies" class="add-sticky-icon ${UI.showStickies?'on':''}" title="Sticky notes" aria-pressed="${UI.showStickies}"><img src="assets/stickies.png" alt=""></button>${UI.showStickies?'<button data-act="new-sticky" class="sticky-plus" title="Add sticky note">＋</button>':''}</div></div>${UI.showStickies&&p().stickyNotes.filter(n=>!n.closed&&(!n.chapterId||n.chapterId===UI.chapterId)).length?`<div class="sticky-margin">${p().stickyNotes.filter(n=>!n.closed&&(!n.chapterId||n.chapterId===UI.chapterId)).map(stickyHtml).join('')}</div>`:''}
 <div class="board-scroll lasso-surface board-page" id="storyboard-scroll"><div class="board-grid page-grid ${show?'with-notes':''}" id="storyboard-grid" style="--card-width:${p()?.viewPrefs.thumbnailSize||195}px;--card-gap:${store.state.settings.spacing}px;--page-rows:${boardRows()};--page-cols:${boardDimensions().cols}">${boardSlots(C,offset)}</div></div><div class="board-bottom board-pagination"><span>${C.length} storyboards</span><div class="board-page-controls"><button data-act="board-prev" ${page===0?'disabled':''} title="Previous page">‹</button><span>Page ${page+1} / ${pages}</span><button data-act="board-next" ${page>=pages-1?'disabled':''} title="Next page">›</button>${page===pages-1&&C.length&&C.length%boardPageSize()===0?`<button data-act="board-add-page" title="Create next page with a blank storyboard">＋ New page</button>`:''}</div></div></main>${UI.right?rightSidebar():`<button class="rail-open right" data-act="toggle-holding" title="Show Holding Area">≡</button>`}</div>`;}
function fitStoryboardPage(){if(UI.screen!=='storyboard')return;const el=$('#storyboard-scroll'),grid=$('#storyboard-grid');if(!el||!grid)return;
 const ratioNum=p().ratio==='9:16'?9/16:p().ratio==='4:3'?4/3:16/9;
 const {cols}=boardDimensions(),rows=boardRows();const gap=Math.max(5,parseFloat(getComputedStyle(grid).columnGap)||12);
 const availableW=Math.max(0,el.clientWidth-30),availableH=Math.max(0,el.clientHeight-18);
 const notes=p().viewPrefs.cardNotesVisible?90:0,rowH=(availableH-(rows-1)*gap)/rows;
 const maximumWidth=Math.min((availableW-(cols-1)*gap)/cols-10,(rowH-24-notes)*ratioNum,p().viewPrefs.thumbnailSize||195);
 grid.style.setProperty('--page-fit-width',Math.max(75,Math.floor(maximumWidth))+'px');grid.style.setProperty('--page-rows',String(rows));grid.style.setProperty('--page-cols',String(cols));
}

function browserMenuActions(){return `<button data-act="project-new">New Project</button><button data-act="folder-new">New Folder</button><button data-act="browser-settings">Settings</button>`;}
function menuItems(){if(UI.screen==='browser')return ['Settings','Shortcuts','Exit'];if(UI.screen==='completion')return ['Storyboard','Print','Settings','Shortcuts','Exit'];if(UI.screen==='print')return ['Storyboard','Completion','Filter & Highlight','Settings','Shortcuts','Exit'];if(UI.screen==='perform')return ['Storyboard','Completion','Print','Settings','Shortcuts','Exit'];return ['Perform','Completion','Print','Filter & Highlight','Settings','Shortcuts','Exit'];}
function menuHtml(){return `<div class="overlay menu-overlay" data-overlay="menu"><nav class="game-menu"><h2 class="display-font">Storyboard Studio</h2>${menuItems().map((x,i)=>`<button class="menu-choice display-font ${UI.focusIndex===i?'focused':''}" data-menu-option="${i}">${x==='Settings'?'<span class="rule"></span>':''}${x==='Exit'?'← ':''}${x}</button>`).join('')}<small>W/S · Enter · Esc / Tab</small></nav></div>`;}
function renderMenu(){document.body.insertAdjacentHTML('beforeend',menuHtml());}
function openMenu(){UI.menu=true;UI.focusIndex=0;renderMenu();}
function closeMenu(){$$('.menu-overlay').forEach(x=>x.remove());UI.menu=false;}
function chooseMenu(i){const item=menuItems()[i];closeMenu();if(item==='Perform'&&p()){actions.perform();return;}if(item==='Storyboard'&&p()){actions.storyboard();return;}if(item==='Settings'){showSettings();return;}if(item==='Shortcuts'){showShortcuts();return;}if(item==='Exit'){if(UI.screen==='browser')render();else leave();return;}if(UI.screen==='browser'){toast('Open a project to use this option');return;}if(item==='Print'){UI.screen='print';render();}else if(item==='Completion'){UI.screen='completion';UI.completionChapterId=null;UI.completionSelected=[];render();}else if(item==='Filter & Highlight')showFilterModal();}

function getTagList(){return [['all','All'],...Object.keys(tagDefs).filter(k=>k!=='cleanup').map(k=>[k,label(k)]),...(p()?.customTags||[]).map(t=>[t.id,t.name])];}
function showFilterModal(){const t=getTagList();modal('Filter & Highlight',`<p>Filter hides other boards. Highlight keeps their positions and helps you find them.</p><label>Filter <select id="filter-select">${t.map(([id,n])=>`<option value="${id}" ${UI.filterTag===id?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label>Highlight <select id="highlight-select"><option value="none">None</option>${t.filter(x=>x[0]!=='all').map(([id,n])=>`<option value="${id}" ${UI.highlightTag===id?'selected':''}>${esc(n)}</option>`).join('')}</select></label><button type="button" class="filter-reset-button" data-act="reset-filter">Reset filter &amp; highlight</button>`,[{text:'Done',action:'apply-filter',primary:true}]);}
function showSettings(){const s=store.state.settings;modal('Settings',`<div class="settings-list"><label>Theme<select data-setting="theme"><option value="light" ${UI.theme==='light'?'selected':''}>Light</option><option value="dark" ${UI.theme==='dark'?'selected':''}>Dark</option></select></label><label>Card numbers<select data-setting="numbering"><option value="global" ${s.numbering==='global'?'selected':''}>Global</option><option value="chapter" ${s.numbering==='chapter'?'selected':''}>Restart per chapter</option></select></label><label>Chapter sidebar info<select data-setting="chapterInfo"><option value="range" ${s.chapterInfo==='range'?'selected':''}>Card range</option><option value="count" ${s.chapterInfo==='count'?'selected':''}>Count</option><option value="hidden" ${s.chapterInfo==='hidden'?'selected':''}>Hidden</option></select></label><label class="inline"><input type="checkbox" data-setting="cardNumbers" ${s.cardNumbers?'checked':''}> Show numbers below cards</label><label>Image padding bars<select data-setting="letterbox"><option value="black" ${s.letterbox==='black'?'selected':''}>Black</option><option value="white" ${s.letterbox==='white'?'selected':''}>White</option></select><small>Color of the empty bars around images that do not fill the card.</small></label><label class="setting-measure"><span class="measure-line"><span>Storyboard size</span><output>${p()?.viewPrefs.thumbnailSize||s.thumbSize}px</output></span><input type="range" min="100" max="360" step="5" data-setting="thumbSize" value="${p()?.viewPrefs.thumbnailSize||s.thumbSize}"></label><label>Storyboard columns (${esc(p()?.ratio||'16:9')} preset) <input type="number" min="1" max="6" data-grid-pref="gridCols" value="${boardDimensions().cols}"></label><label>Storyboard rows (${esc(p()?.ratio||'16:9')} preset) <input type="number" min="1" max="7" data-grid-pref="gridRows" value="${boardDimensions().rows}"></label><label class="setting-measure"><span class="measure-line"><span>Card spacing</span><output>${s.spacing}px</output></span><input type="range" min="8" max="65" data-setting="spacing" value="${s.spacing}"></label><label class="setting-measure"><span class="measure-line"><span>Note font size</span><output>${s.noteSize}px</output></span><input type="range" min="10" max="24" data-setting="noteSize" value="${s.noteSize}"></label><label class="inline"><input data-setting="sfx" type="checkbox" ${s.sfx?'checked':''}> UI sounds</label><label>Sound volume <input type="range" min="0" max="1" step=".05" data-setting="sfxVolume" value="${s.sfxVolume??.4}"></label><label class="inline"><input data-setting="animations" type="checkbox" ${s.animations?'checked':''}> Animations</label><button data-act="history-modal">Session history (${store.session.length})</button></div>`,[{text:'Close',action:'close-modal',primary:true}]);}
function showShortcuts(){modal('Shortcuts',`<div class="shortcut-grid">${[['Tab','App menu'],['WASD / Arrows','Navigate cards'],['Space','Quick Look'],['Q / E','Cycle variants'],['R','Holding Area'],['Delete','Delete selection'],['⌘/Ctrl+Z','Undo'],['⌘/Ctrl+⇧Z / Ctrl+Y','Redo'],['Drag empty space','Lasso selection'],['Double-click chapter','Rename chapter'],['Enter while renaming','Save chapter name'],['P','Perform / stop'],['Esc','Close menu or selection']].map(([k,v])=>`<kbd>${esc(k)}</kbd><span>${esc(v)}</span>`).join('')}</div><label class="inline"><input id="alt-undo" type="checkbox" ${store.state.settings.altUndoKeys?'checked':''}> N/M alternate undo/redo</label>`,[{text:'Done',action:'close-modal',primary:true}]);}
function modal(title,body,buttons=[{text:'Cancel',action:'close-modal'}]){UI.modal={title,body,buttons};renderModal();}
function renderModal(){$$('.modal-overlay').forEach(x=>x.remove());const m=UI.modal;if(!m)return;const node=document.createElement('div');node.className='overlay modal-overlay';node.dataset.overlay='modal';node.innerHTML=`<section class="modal-card"><h2 class="display-font">${esc(m.title)}</h2><div class="modal-body">${m.body}</div><div class="modal-buttons">${m.buttons.map((b,i)=>`<button data-modal-btn="${b.action}" class="${b.primary?'primary':''} ${b.danger?'danger':''} ${i===0?'modal-selected':''}">${esc(b.text)}</button>`).join('')}</div></section>`;document.body.append(node);setTimeout(()=>$('.modal-card input:not([type="checkbox"]):not([type="range"]),.modal-card select')?.focus(),10);}
function closeModal(){UI.modal=null;$('.modal-overlay')?.remove();}
function newProjectDialog(){modal('New Project',`<label>Project name<input id="project-title" placeholder="Name your project" autocomplete="off"></label><label>Format<select id="project-ratio"><option>16:9</option><option>9:16</option><option>4:3</option></select></label>`,[{text:'Cancel',action:'close-modal'},{text:'Create',action:'confirm-new-project',primary:true}]);}
const folderColors=[5,36,58,142,195,230,275,320,350];
function selectFolderColor(button){const hidden=$('#folder-hue');if(!hidden)return;hidden.value=button.dataset.folderHue;$$('[data-folder-hue]',button.parentElement).forEach(el=>{const active=el===button;el.classList.toggle('selected',active);el.setAttribute('aria-pressed',String(active));});uiSound();}
function folderDialog(id=null){const f=store.state.folders.find(x=>x.id===id);const selected=Number(f?.hue??350);modal(f?'Edit Folder':'New Folder',`<label>Name<input id="folder-name" value="${esc(f?.name||'')}" placeholder="Folder name"></label><div class="folder-colors-field"><div class="folder-color-heading">Folder color</div><div class="folder-color-swatches" role="group" aria-label="Folder color">${folderColors.map((h,i)=>`<button type="button" data-folder-hue="${h}" class="${h===selected?'selected':''}" aria-pressed="${h===selected}" title="Color ${i+1}" style="--swatch-hue:${h}" aria-label="Color ${i+1}"></button>`).join('')}</div><input type="hidden" id="folder-hue" value="${selected}"></div>`,[{text:'Cancel',action:'close-modal'},{text:'Save',action:f?'save-folder':'create-folder',primary:true}]);UI.editFolderId=id;}
function enterProject(id){store.open(id);UI.screen='storyboard';UI.selectedBrowser=[];UI.chapterId=chapters()[0]?.id;UI.boardPages={};UI.selected=[];UI.bucketSelected=[];UI.menu=false;UI.modal=null;UI.performIdx=0;UI.performChapter='all';UI.takeId=p()?.perform.activeTakeId;render();}
function leave(){stopAudio();UI.screen='browser';store.open(null);UI.selected=[];UI.selectedBrowser=[];UI.menu=false;UI.modal=null;UI.quick=false;store.save();render();}
function highlightNext(){const matches=activeCards().filter(s=>tags(p(),s).includes(UI.highlightTag));if(!matches.length)return toast('No matching cards');UI.highlightIndex=(UI.highlightIndex+1)%matches.length;const el=$(`[data-card="${matches[UI.highlightIndex].id}"]`);el?.scrollIntoView({behavior:'smooth',block:'center'});UI.selected=[matches[UI.highlightIndex].id];markSelected();}
function refreshHighlights(){if(UI.screen!=='storyboard')return;const active=UI.highlightTag!=='none';$('#storyboard-grid')?.classList.toggle('highlight-mode',active);$$('.story-entry[data-card]').forEach(el=>el.classList.toggle('highlighted',active&&tags(p(),item(el.dataset.card)).includes(UI.highlightTag)));}
function markSelected(){for(const el of $$('[data-card]')){const arr=el.dataset.inBucket?UI.bucketSelected:UI.selected;el.classList.toggle('selected',arr.includes(el.dataset.card));}}
function selectCard(id,bucket=false,multi=false){const key=bucket?'bucketSelected':'selected';if(!multi){UI.selected=[];UI.bucketSelected=[];UI[key]=[id];}else UI[key]=UI[key].includes(id)?UI[key].filter(x=>x!==id):[...UI[key],id];UI.selectionZone=bucket?'bucket':'main';markSelected();}
function toggleNotes(){const first=boardPage()*boardPageSize();change('Toggle card notes',s=>{const v=p().viewPrefs;v.cardNotesVisible=!v.cardNotesVisible;UI.boardPages[UI.chapterId]=Math.floor(first/boardPageSize());});}
function archiveSticky(id){change('Archive sticky',s=>{const n=p().stickyNotes.find(x=>x.id===id);if(!n)return;if((n.text||'').trim())p().archivedStickies.push(n);p().stickyNotes=p().stickyNotes.filter(x=>x.id!==id);});}
function blankAt(index){change('Insert blank card',s=>{const cs=cardsInChapter(),newcard=card(UI.chapterId);let raw=index<cs.length?p().stories.findIndex(x=>x.id===cs[index].id):cs.length?p().stories.findIndex(x=>x.id===cs[cs.length-1].id)+1:p().stories.length;p().stories.splice(Math.max(0,raw),0,newcard);UI.selected=[newcard.id];revealCardPage(newcard.id);UI.boardPages[UI.chapterId]=Math.floor(index/boardPageSize());});}
function renumberReuseCopies(project){const groups=new Map();for(const x of allCards(project)){if(!x.reuseOf)continue;const arr=groups.get(x.reuseOf)||[];arr.push(x);groups.set(x.reuseOf,arr);}for(const copies of groups.values()){copies.sort((a,b)=>(Number(a.reuseIndex)||Infinity)-(Number(b.reuseIndex)||Infinity));copies.forEach((x,i)=>x.reuseIndex=i+1);}}
function deleteSelected(){const ids=UI.selectionZone==='bucket'?UI.bucketSelected:UI.selected;if(!ids.length)return;change(`Delete ${ids.length} card${ids.length>1?'s':''}`,s=>{for(const key of ['stories','unassigned','lost','archived'])p()[key]=p()[key].filter(x=>!ids.includes(x.id));if(UI.rightMode==='assets')s.globalAssets=s.globalAssets.filter(x=>!ids.includes(x.id));renumberReuseCopies(p());UI.selected=[];UI.bucketSelected=[];});}
function transfer(ids,kind,chapterId=null,index=null){const selected=[...new Set(ids)];if(!selected.length)return;
 const targetChapter=chapterId||UI.chapterId, original=kind==='stories'?chapterCards(p(),targetChapter):[];
 const remainingAnchor=index==null?null:original.slice(index).find(x=>!selected.includes(x.id))?.id||null;
 change(`Move ${selected.length} card(s)`,s=>{let moved=[];for(const k of ['stories','unassigned','lost','archived']){moved.push(...p()[k].filter(x=>selected.includes(x.id)));p()[k]=p()[k].filter(x=>!selected.includes(x.id));}
 const global=store.state.globalAssets.filter(x=>selected.includes(x.id));moved=selected.map(id=>moved.find(s=>s.id===id)||global.find(x=>x.id===id)).filter(Boolean).map(x=>global.some(g=>g.id===x.id)?{...structuredClone(x),id:uid('story'),chapterId:targetChapter}:x);
 if(kind==='stories'){moved.forEach(x=>x.chapterId=targetChapter);const dest=p().stories,existing=chapterCards(p(),targetChapter);let at=remainingAnchor?dest.findIndex(x=>x.id===remainingAnchor):-1;
 if(at<0)at=existing.length?dest.findIndex(x=>x.id===existing.at(-1).id)+1:dest.length;
 dest.splice(Math.max(0,at),0,...moved);UI.selected=moved.map(x=>x.id);UI.bucketSelected=[];UI.chapterId=targetChapter;
 const first=chapterCards(p(),targetChapter).findIndex(x=>x.id===moved[0]?.id);if(first>=0)UI.boardPages[targetChapter]=Math.floor(first/boardPageSize());
 }else if(kind==='assets'){for(const x of moved)if(!store.state.globalAssets.some(y=>y.id===x.id))store.state.globalAssets.push(x);}
 else{moved.forEach(x=>{if(kind==='lost'){x.lostScope=UI.lostScope;if(UI.lostScope==='chapter')x.chapterId=UI.chapterId;}});p()[kind].push(...moved);UI.bucketSelected=moved.map(x=>x.id);UI.selected=[];}});}

function showContext(x,y,items){$('.context-pop')?.remove();const el=document.createElement('div');el.className='context-pop';el.innerHTML=items.map(({name,act,cls})=>name==='---'?'<hr>':`<button data-context="${act}" class="${cls||''}">${esc(name)}</button>`).join('');document.body.append(el);const rect=el.getBoundingClientRect();el.style.left=Math.max(8,Math.min(x,innerWidth-rect.width-8))+'px';el.style.top=Math.max(8,Math.min(y,innerHeight-rect.height-8))+'px';}
function cardContext(e,id,bucket=false){const already=(bucket?UI.bucketSelected:UI.selected).includes(id);if(!already)selectCard(id,bucket,false);else UI.selectionZone=bucket?'bucket':'main';UI.contextCardId=id;const selected=(bucket?UI.bucketSelected:UI.selected).length;
showContext(e.clientX,e.clientY,[{name:'Manage tags',act:'card-tags'},{name:'Replace image…',act:'replace-card'},{name:'Make reusable copy',act:'reuse'},{name:'Move to Lost',act:'move-lost'},{name:'Archive',act:'move-archived'},{name:'---'},{name:'Delete',act:'delete-cards',cls:'danger'}]);}
function tagDialog(id){UI.contextCardId=id;const current=item(id);modal('Manage Tags',`<div class="tag-choices">${[['animation','Animation'],['review','Review'],['done','Done'],...(p()?.customTags||[]).map(x=>[x.id,x.name])].map(([id,n])=>`<label class="tag-row" data-tag-row="${id}"><input data-toggle-tag="${id}" type="checkbox" ${(id==='done'?completionOf(p(),current)==='green':(current.tags||[]).includes(id))?'checked':''}><span style="--tag:${color(id)}" class="tag-badge">${esc(symbol(id))}</span>${esc(n)}</label>`).join('')}</div><p class="muted">Blank, Variants and Reused update automatically. Done is shared with Completion.</p><button data-act="create-tag-dialog">＋ Create new tag</button>`,[{text:'Done',action:'close-modal',primary:true}]);}
function quickTagMenu(el){const id=el.dataset.id||UI.contextCardId;if(!id)return;UI.contextCardId=id;const r=el.getBoundingClientRect(),selected=item(id)?.tags||[];showContext(r.left,r.bottom+4,[{name:`${selected.includes('animation')?'✓ ':''}Animation`,act:'quick-tag-animation'},{name:`${selected.includes('review')?'✓ ':''}Review`,act:'quick-tag-review'},{name:`${completionOf(p(),item(id))==='green'?'✓ ':''}Done`,act:'quick-tag-done'},{name:'---'},{name:'Manage tags…',act:'card-tags'}]);}
function newTagDialog(){modal('New Tag',`<label>Name<input id="tag-name" placeholder="Tag name"></label><label>Color <input type="color" id="tag-color" value="#79a9d9"></label><label>Symbol<select id="tag-icon">${['◆','!', '★','♫','✦','✓','◇','♻','●'].map(x=>`<option>${x}</option>`).join('')}</select></label>`,[{text:'Cancel',action:'close-modal'},{text:'Create',action:'confirm-tag',primary:true}]);}
function editCardNote(id){const s=item(id);if(!s)return;UI.editNoteId=id;modal('Card Note',`<label class="note-editor-label">Text<textarea id="note-editor-text" rows="10" placeholder="Write a note about this storyboard…">${esc(s.note||'')}</textarea></label>`,[{text:'Cancel',action:'close-modal'},{text:'Save',action:'save-card-note',primary:true}]);}
function renameChapter(id){const ch=p()?.chapters.find(c=>c.id===id);if(!ch)return;UI.contextChapterId=id;modal('Rename Chapter',`<label>Chapter name<input id="rename-chapter-input" maxlength="180" value="${esc(ch.name)}"></label>`,[{text:'Cancel',action:'close-modal'},{text:'Rename',action:'confirm-rename-chapter',primary:true}]);}
function chapterContext(e,id){UI.contextChapterId=id;const chapterItem=p().chapters.find(x=>x.id===id);showContext(e.clientX,e.clientY,[{name:'Rename',act:'chapter-rename'},{name:'Add Subchapter',act:'subchapter-add'},{name:chapterItem?.unused?'Restore':'Move to Unused',act:'chapter-unused'},{name:'Export this page (PNG)',act:'chapter-page-export'},{name:'Export chapter cards (PNG)',act:'chapter-cards-export'},{name:'---'},{name:'Delete chapter…',act:'chapter-delete',cls:'danger'}]);}
function selectedChapter(id){if(!p().chapters.some(x=>x.id===id))return;UI.chapterId=id;UI.selected=[];UI.highlightIndex=0;render();}
function deleteChapter(id){if(p().chapters.length===1)return toast('A project needs at least one chapter');const c=p().chapters.find(c=>c.id===id);if(!c.unused&&chapters().length<=1)return toast('Keep at least one active chapter');modal('Delete Chapter',`<p>Delete <strong>${esc(c.name)}</strong>?</p><p>Its cards and direct subchapters will move to Not Assigned. No drawings will be destroyed.</p>`,[{text:'Cancel',action:'close-modal'},{text:'Delete Chapter',action:'confirm-delete-chapter',danger:true}]);UI.contextChapterId=id;}
function quickLook(){if(!(UI.selected.length||UI.bucketSelected.length))return;UI.quick=true;renderQuick();}
function renderQuick(){$('.quick-overlay')?.remove();if(!UI.quick)return;const s=item(UI.selected[0]||UI.bucketSelected[0]);if(!s)return;const v=visual(p(),s),el=document.createElement('div');el.className='overlay quick-overlay';el.innerHTML=`<div class="quick-card"><div class="quick-visual" style="aspect-ratio:${ratio(p())};width:min(70vw, ${p().ratio==='9:16'?42:p().ratio==='4:3'?100:133}vh)">${imageHtml(s)}</div><div class="quick-caption"><strong>${position(p(),s.id)||''} ${v.count>1?` · ${String.fromCharCode(65+v.index)} (${v.count})`:''}</strong><p>${esc(s.note||'')}</p><small>Space / Esc to close · A/D to browse · Q/E for variants</small></div></div>`;document.body.append(el);attachImages(el);}
function performHtml(){const all=performCards(),c=all[Math.min(UI.performIdx,all.length-1)],s=p();return `${toolbar()}<div class="perform-shell"><div class="perform-tools"><label>Chapter <select id="perform-chapter"><option value="all">All chapters</option>${chapters().map(c=>`<option value="${c.id}" ${UI.performChapter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div><button data-act="new-take" title="New take">＋ Take</button><button data-act="perform-export" title="Export current take as video">Export MP4</button></div></div><section class="perform-stage"><div class="perform-stage-top"><strong class="perf-chapter-label">${esc(c? p().chapters.find(x=>x.id===c.chapterId)?.name||'':'No boards')}</strong><strong class="perf-card-num">${c?position(p(),c.id):''}</strong></div><div class="perform-stage-grid"><div class="perform-tags" id="perform-tags">${c?tags(s,c).map(t=>`<div class="perform-tag-item">${badge(t)} ${esc(label(t))}</div>`).join(''):''}<button data-act="perform-add-tag" class="perform-add-tag" title="Edit current card tags">＋</button></div><div class="perform-visual" id="perform-visual" style="aspect-ratio:${ratio(s)}">${c?imageHtml(c):'<div class="blank-art">NO STORYBOARD</div>'}</div><textarea id="perform-note" placeholder="Card notes (pauses playback while editing)">${esc(c?.note||'')}</textarea></div><div class="perform-stage-footer"><button data-act="take-menu" class="take-label">${esc(activeTake()?.name||'Take 1')}</button><span class="perform-state" id="perform-state">IDLE</span><span id="perform-clock">00:00.000</span></div></section><div class="audio-panel"><div class="wave-tools"><span class="audio-title">${s.perform.audioAssetId?'AUDIO TIMELINE':'Drop or choose WAV / MP3 audio'}</span><span class="grow"></span><button data-act="audio-choose" title="Import/replace audio">♫</button><button data-act="wave-minus" title="Zoom out">−</button><button data-act="wave-plus" title="Zoom in">＋</button></div><div class="wave-viewport" id="wave-viewport" style="height:${UI.performWaveHeight}px"><canvas id="wave-canvas"></canvas><div id="wave-marker-layer"></div></div><div class="wave-resizer" id="wave-resizer" title="Drag to resize waveform"></div></div><div class="perform-controls"><button data-act="perform-stop">■ Stop</button><button class="${UI.recording?'danger':'primary'}" data-act="perform-record">${UI.recording?'■ Stop Performing':'● Perform'}</button><button data-act="perform-play">${UI.playing?'Ⅱ Pause':'▶ Play'}</button><span class="grow"></span><span class="muted">← / → Card · Space Play · P Perform</span></div><div class="perform-strip" id="perform-strip">${all.map((x,i)=>{const n=i-UI.performIdx,art=imageHtml(x);return `<button data-perform-index="${i}" style="--offset:${n};aspect-ratio:${ratio(s)}" class="perform-strip-card ${i===UI.performIdx?'current':n===1||n===2?'next':'faded'}">${art}</button>`;}).join('')}</div></div>`;}
function performCards(){return UI.performChapter==='all'?ordered(p()):chapterCards(p(),UI.performChapter);}
function refreshPerform(){const s=performCards()[UI.performIdx];if(!s)return;const v=visual(p(),s),node=$('#perform-visual');if(node){node.innerHTML=imageHtml(s);attachImages(node);}const n=$('#perform-note');if(n&&document.activeElement!==n)n.value=s.note||'';if($('.perf-card-num'))$('.perf-card-num').textContent=position(p(),s.id);if($('.perf-chapter-label'))$('.perf-chapter-label').textContent=p().chapters.find(c=>c.id===s.chapterId)?.name||'';if($('#perform-tags'))$('#perform-tags').innerHTML=tags(p(),s).map(t=>`<div class="perform-tag-item">${badge(t)} ${esc(label(t))}</div>`).join('');$$('.perform-strip-card').forEach(el=>{const i=+el.dataset.performIndex,n=i-UI.performIdx;el.style.setProperty('--offset',n);el.className=`perform-strip-card ${i===UI.performIdx?'current':n===1||n===2?'next':'faded'}`;});}
function performanceTime(){return activeAudio?.currentTime||0;}
function timecode(n){const t=Math.max(0,n||0),m=Math.floor(t/60),sec=Math.floor(t%60),ms=Math.floor(t%1*1000);return `${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}.${String(ms).padStart(3,'0')}`;}
async function setupAudio(){if(UI.screen!=='perform'||!p())return;const id=p().perform.audioAssetId;if(!id){stopAudio(true);return;}if(activeAudio?.dataset.assetId===id)return;stopAudio(true);const a=await window.SSDB.getAsset(id);if(UI.screen!=='perform'||!a)return;let url=a.dataUrl;if(a.blob){url=URL.createObjectURL(a.blob);}activeAudio=new Audio(url);activeAudio.dataset.assetId=id;activeAudio.preload='auto';activeAudio.addEventListener('ended',()=>{stopRecording();UI.playing=false;$('#perform-state')&&( $('#perform-state').textContent='ENDED');});activeAudio.addEventListener('error',()=>toast('Audio could not be opened.'));}
async function chooseAudio(){files.accept='.wav,.mp3,audio/*';files.multiple=false;files.dataset.intent='audio';files.click();}
async function importAudio(f){const reader=new FileReader();const dataUrl=await new Promise((resolve,reject)=>{reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f);});const id=uid('audio');await SSDB.putAsset({id,dataUrl,sourceName:f.name,createdAt:Date.now()});stopAudio(true);change('Import audio',s=>{p().perform.audioAssetId=id;p().perform.waveform=[];p().perform.chapterAnchors={};p().perform.duration=0;});const AudioContext=window.AudioContext||window.webkitAudioContext;try{const buf=await f.arrayBuffer(),ctx=new AudioContext(),decoded=await ctx.decodeAudioData(buf.slice(0));const ch=decoded.getChannelData(0),chunk=Math.ceil(ch.length/700),peaks=[];for(let i=0;i<ch.length;i+=chunk){let top=0;for(let j=i;j<Math.min(ch.length,i+chunk);j++)top=Math.max(top,Math.abs(ch[j]));peaks.push(+top.toFixed(4));}await ctx.close();change('Cache waveform',s=>{p().perform.waveform=peaks;p().perform.duration=decoded.duration;},{render:false});}catch(e){console.warn('Could not decode waveform',e);}render();}
async function audioPlay(){await setupAudio();if(!activeAudio)return toast('Import audio first');try{await activeAudio.play();UI.playing=true;startTicker();updateStateBadge();}catch(e){toast('Audio playback failed: '+(e?.message||'unknown error'));}}
function audioPause(){activeAudio?.pause();UI.playing=false;stopRecording();updateStateBadge();}
function stopAudio(clear=false){audioPause();cancelAnimationFrame(performRAF);if(clear){activeAudio?.pause();activeAudio=null;}UI.performTime=0;}
function updateStateBadge(){const e=$('#perform-state');if(e)e.textContent=UI.recording?'● PERFORMING':UI.playing?'PLAYBACK':'IDLE';$('#perform-clock')&&($('#perform-clock').textContent=timecode(performanceTime()));}
function startTicker(){cancelAnimationFrame(performRAF);const tick=()=>{if(UI.screen!=='perform'||!activeAudio)return;UI.performTime=activeAudio.currentTime;updateStateBadge();updatePlayhead();if(UI.recording){const r=activeTake()?.ranges?.at(-1);if(r)r[1]=Math.max(r[0],UI.performTime);store.save();if(performance.now()-lastWaveDraw>140){lastWaveDraw=performance.now();drawWave();}}else if(UI.playing){const cue=[...(activeTake()?.cues||[])].filter(c=>c.time<=UI.performTime).at(-1);if(cue){const i=performCards().findIndex(s=>s.id===cue.storyId);if(i>=0&&i!==UI.performIdx){UI.performIdx=i;refreshPerform();}}}if(UI.playing)performRAF=requestAnimationFrame(tick);};performRAF=requestAnimationFrame(tick);}
async function startPerform(){if(!p()?.perform.audioAssetId)return toast('Import audio before performing');await audioPlay();if(!activeAudio||activeAudio.paused)return;const at=activeAudio.currentTime,t=activeTake();store.change('Start performing from playhead',s=>{t.cues=t.cues.filter(c=>c.time<at);t.ranges=t.ranges.map(r=>[r[0],Math.min(r[1],at)]).filter(r=>r[1]>r[0]);t.ranges.push([at,at]);},{silent:true});UI.recording=true;recordCue();updateStateBadge();drawWave();}
function stopRecording(){if(!UI.recording)return;UI.recording=false;const ranges=activeTake()?.ranges;if(ranges?.length){const r=ranges.at(-1);r[1]=Math.max(r[1],performanceTime());if(r[1]<=r[0])ranges.pop();}store.save();drawWave();updateStateBadge();}
function recordCue(){if(!UI.recording||!activeAudio||activeAudio.paused)return;const s=performCards()[UI.performIdx],t=activeTake();if(!s||!t)return;const tm=activeAudio.currentTime;t.cues.push({time:tm,storyId:s.id});t.cues.sort((a,b)=>a.time-b.time);store.save();drawWave();}
function performMove(d){const a=performCards();if(!a.length)return;const next=Math.max(0,Math.min(a.length-1,UI.performIdx+d));if(next===UI.performIdx)return;UI.performIdx=next;refreshPerform();if(UI.recording)recordCue();}
function seekAudio(t){if(!activeAudio)return;stopRecording();activeAudio.currentTime=Math.max(0,Math.min(activeAudio.duration||Infinity,t));UI.performTime=activeAudio.currentTime;updatePlayhead();updateStateBadge();}
function drawWave(){const c=$('#wave-canvas'),port=$('#wave-viewport');if(!c||!port)return;const data=p()?.perform.waveform||[],height=Math.max(32,UI.performWaveHeight-6),width=Math.max(port.clientWidth,port.clientWidth*UI.performZoom);c.width=Math.round(width*devicePixelRatio);c.height=Math.round(height*devicePixelRatio);c.style.width=width+'px';c.style.height=height+'px';const ctx=c.getContext('2d');ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.clearRect(0,0,width,height);const d=p()?.perform.duration||activeAudio?.duration||1;const ranges=activeTake()?.ranges||[];for(const [start,end] of ranges){ctx.fillStyle='rgba(62,206,151,.18)';ctx.fillRect(start/d*width,0,(end-start)/d*width,height);}const count=data.length||1,step=width/count;ctx.fillStyle='#79afff';for(let i=0;i<count;i++){const v=data[i]||0,y=(1-Math.max(.025,v))*height/2;ctx.fillRect(i*step,y,Math.max(1,step*.8),height-y*2);}ctx.strokeStyle='#5e83c6';ctx.beginPath();ctx.moveTo(0,height/2);ctx.lineTo(width,height/2);ctx.stroke();const layer=$('#wave-marker-layer');if(layer){layer.innerHTML=[...(activeTake()?.cues||[]).map(c=>`<span class="wave-cue" style="left:${c.time/d*width}px" title="Card ${position(p(),c.storyId)} · ${timecode(c.time)}"></span>`),...Object.entries(p()?.perform.chapterAnchors||{}).map(([id,t])=>`<span class="wave-chapter" style="left:${t/d*width}px" title="${esc(p().chapters.find(c=>c.id===id)?.name||'Chapter')} · ${timecode(t)}"></span>`)].join('')+`<span class="wave-playhead" id="wave-playhead"></span>`;layer.style.width=width+'px';layer.style.height=height+'px';}updatePlayhead();}
function updatePlayhead(){const n=$('#wave-playhead'),c=$('#wave-canvas');if(n&&c)n.style.left=((performanceTime())/(p()?.perform.duration||activeAudio?.duration||1)*c.clientWidth)+'px';}
function chapterAnchor(){if(!p())return;const id=UI.performChapter==='all'?performCards()[UI.performIdx]?.chapterId:UI.performChapter;if(!id)return;const t=performanceTime();change('Set chapter start',s=>{p().perform.chapterAnchors[id]=t;},{render:false});drawWave();toast(`Chapter starts at ${timecode(t)}`);}
function printHtml(){const opt=UI.print;const pages=printPages();return `${toolbar().replace('<div class="top-actions">','<div class="top-actions"><button data-act="storyboard">← Editable</button>')}<div class="print-shell">${chapterSidebar({print:true})}<main class="print-center"><div class="print-title"><h2>Final Printable</h2><small>${pages.length} page${pages.length!==1?'s':''}</small></div><div id="paper-list" class="paper-list">${pages.map((page,i)=>`<section data-print-chapter="${page.chapter.id}" class="paper ${opt.orientation}" style="--print-cols:${opt.cols};--print-rows:${opt.rows};--print-gap:${opt.spacing*8}px"><div class="paper-header">${opt.projectTitle?`<strong>${esc(p().name)}</strong>`:''}${opt.chapterTitle?`<span>${esc(page.chapter.name)}</span>`:''}</div><div class="paper-grid">${page.cards.map(s=>`<div class="paper-card"><div class="paper-art" style="--print-image-ratio:${ratio(p())};aspect-ratio:${ratio(p())}">${imageHtml(s)}${opt.tags?`<div class="corner-tags">${tags(p(),s).slice(0,3).map(badge).join('')}</div>`:''}</div>${opt.numbers?`<span class="paper-num">${position(p(),s.id,store.state.settings.numbering)}</span>`:''}${opt.notes?`<p style="font-size:${opt.noteFont}px">${esc(s.note)}</p>`:''}</div>`).join('')}</div><footer>${opt.range?`<span>${page.range}</span>`:'<span></span>'}${opt.pageNum?`<span>${i+1} / ${pages.length}</span>`:''}</footer></section>`).join('')}</div></main><aside class="print-options"><h3>Print layout</h3><div class="mini-switch"><button data-print-orientation="portrait" class="${opt.orientation==='portrait'?'active':''}">Vertical</button><button data-print-orientation="landscape" class="${opt.orientation==='landscape'?'active':''}">Horizontal</button></div><div class="two-cols"><label>Columns<input type="number" min="1" max="6" data-print="cols" value="${opt.cols}"></label><label>Rows max<input type="number" min="1" max="8" data-print="rows" value="${opt.rows}"></label></div><label>Spacing <input type="range" min="0.5" max="2" step=".1" data-print="spacing" value="${opt.spacing}"></label><label>Note font size<input type="range" min="8" max="22" data-print="noteFont" value="${opt.noteFont}"></label><div class="print-checks">${[['notes','Notes'],['tags','Tags'],['numbers','Card numbers'],['stickers','Stickers'],['projectTitle','Project title'],['chapterTitle','Chapter title'],['range','Card range'],['pageNum','Page number'],['blankWhite','Blank cards white']].map(([key,n])=>`<label><input type="checkbox" data-print="${key}" ${opt[key]?'checked':''}> ${n}</label>`).join('')}</div><div class="print-export"><button data-act="print-pdf">Export PDF</button><button data-act="print-png">Export PNG pages</button><button data-act="print-cards">Export cards as PNGs</button></div></aside></div>`;}
function printPages(chapterId=null){
 const opt=UI.print,out=[],cols=Math.max(1,Math.min(6,Number(opt.cols)||3)),rows=Math.max(1,Math.min(8,Number(opt.rows)||5));
 for(const ch of chapters()){
   if(chapterId&&ch.id!==chapterId)continue;
   const cards=chapterCards(p(),ch.id);if(!cards.length)continue;
   const maxRows=Math.min(rows, p().ratio==='9:16' ? (opt.orientation==='landscape'?1:2) : p().ratio==='4:3' ? (opt.orientation==='landscape'?2:3) : opt.notes ? (opt.orientation==='landscape'?2:3) : (opt.orientation==='landscape'?3:5));
   for(let off=0;off<cards.length;off+=cols*maxRows){
     const group=cards.slice(off,off+cols*maxRows),nums=group.map(s=>position(p(),s.id,store.state.settings.numbering));
     out.push({chapter:ch,cards:group,range:nums.length===1?nums[0]:`${nums[0]}–${nums.at(-1)}`});
   }
 }
 return out;
}
function completionStatus(card){return completionOf(p(),card);}
function completionSummary(){const byChapter=chapters().map(c=>{const cards=chapterCards(p(),c.id);const done=cards.filter(s=>completionStatus(s)==='green').length,half=cards.filter(s=>completionStatus(s)==='yellow').length;return {c,cards,done,half,total:cards.length,pct:cards.length?Math.round(100*(done+half*.5)/cards.length):0};});const total=byChapter.reduce((n,x)=>n+x.total,0),done=byChapter.reduce((n,x)=>n+x.done,0),half=byChapter.reduce((n,x)=>n+x.half,0);return {byChapter,total,done,half,pct:total?Math.round(100*(done+half*.5)/total):0};}
function completionCardHtml(s){const status=completionStatus(s),selected=UI.completionSelected.includes(s.id);return `<div class="completion-card ${status} ${selected?'selected':''}" data-completion-card="${s.id}"><div class="completion-art" style="aspect-ratio:${ratio(p())}">${imageHtml(s)}<div class="completion-tint"></div><div class="completion-tag-layer">${tags(p(),s).filter(tag=>tag!=='done'&&tag!=='blank').map(badge).join('')}</div>${status==='green'?'<span class="completion-check">✓</span>':''}<div class="completion-colors" title="Set completion status">${['red','yellow','green'].map(status=>`<button data-completion-status="${status}" data-card-id="${s.id}" class="${status}" title="${status==='red'?'Not started':status==='yellow'?'In progress':'Completed'}" aria-label="${status}"></button>`).join('')}</div></div><div class="completion-meta"><span>${esc(position(p(),s.id,store.state.settings.numbering))}</span>${s.reuseOf?`<span class="completion-copy-label">${esc(copyTitle(s))}</span>`:''}</div></div>`;}
function completionSelect(id,multi=false,range=false){const cards=chapterCards(p(),UI.completionChapterId).map(c=>c.id);if(range&&UI.completionAnchor&&cards.includes(UI.completionAnchor)){const a=cards.indexOf(UI.completionAnchor),b=cards.indexOf(id);UI.completionSelected=[...new Set([...UI.completionSelected,...cards.slice(Math.min(a,b),Math.max(a,b)+1)])];}else if(!multi)UI.completionSelected=[id];else UI.completionSelected=UI.completionSelected.includes(id)?UI.completionSelected.filter(x=>x!==id):[...UI.completionSelected,id];if(!range)UI.completionAnchor=id;$$('[data-completion-card]').forEach(el=>el.classList.toggle('selected',UI.completionSelected.includes(el.dataset.completionCard)));}
function completionSetStatus(status,id){if(!['red','yellow','green'].includes(status))return;const ids=id==null?[...UI.completionSelected]:UI.completionSelected.includes(id)?UI.completionSelected:[id];if(!ids.length)return toast('Select at least one card');change('Set completion status',state=>{for(const id of ids){const c=item(id);if(c)setFamilyCompletion(p(),c,status);}const all=chapters().flatMap(x=>chapterCards(p(),x.id));p().completion=all.length?Math.round(all.reduce((sum,c)=>sum+(completionStatus(c)==='green'?1:completionStatus(c)==='yellow'?.5:0),0)*100/all.length):0;});}
function completionHtml(){const {byChapter,total,done,half,pct}=completionSummary(),active=byChapter.find(x=>x.c.id===UI.completionChapterId);return `${toolbar()}<div class="completion-layout"><aside class="completion-chapter-sidebar"><h2 class="display-font">Completion</h2><button class="completion-overview ${active?'':'selected'}" data-act="completion-overview">Overview <strong>${pct}%</strong></button><div class="completion-chapter-list">${byChapter.map(({c,total,done,pct})=>`<button class="completion-chapter-option ${active?.c.id===c.id?'selected':''}" data-complete-chapter="${c.id}"><span>${esc(c.name)}</span><small>${pct}%</small><span class="completion-mini-progress"><i style="width:${pct}%"></i></span></button>`).join('')}</div></aside><main class="completion-content">${active?`<div class="completion-content-header"><h2>${esc(active.c.name)}</h2><small>${active.pct}% · ${active.done} finished, ${active.half} in progress</small></div><div class="completion-batch">${['red','yellow','green'].map(x=>`<button class="completion-batch-btn ${x}" data-completion-status="${x}" aria-label="Mark selected cards ${x}" title="Mark selected cards ${x}"><span></span>${x==='red'?'Not started':x==='yellow'?'In progress':'Done'}</button>`).join('')}</div><div class="completion-card-grid lasso-surface" id="completion-grid" style="--completion-width:${UI.completionThumb}px">${active.cards.map(completionCardHtml).join('')}</div><footer class="completion-footer">Cmd/Ctrl-click or Shift-click to select multiple cards</footer>`:`<div class="completion-overview-main"><h1 class="display-font">Completion</h1><div class="completion-score">${pct}%</div><div class="progress-track"><div style="width:${pct}%"></div></div><p>${done} complete · ${half} in progress · ${total} total</p><div class="completion-overview-guide">Choose a chapter on the left to review its cards.</div></div>`}</main></div>`;}

// ---------- Export and compatibility ----------
const pixels=r=>r==='9:16'?[1080,1920]:r==='4:3'?[1920,1440]:[1920,1080];
function drawExportTags(ctx,story,x,y,width,height,{inset=0.025}={}){if(!UI.print.tags)return;const visible=tags(p(),story).slice(0,4);if(!visible.length)return;
 const size=Math.max(16,Math.min(width*.072,height*.15)),gap=Math.max(3,size*.12),left=x+width-width*inset-size,top=y+height*inset;
 ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`bold ${Math.floor(size*.65)}px sans-serif`;
 visible.forEach((tag,i)=>{const xx=left-i*(size+gap);ctx.fillStyle=color(tag);ctx.fillRect(xx,top,size,size);ctx.strokeStyle='#46515b';ctx.lineWidth=Math.max(1,size*.025);ctx.strokeRect(xx,top,size,size);ctx.fillStyle='#202a35';ctx.fillText(symbol(tag),xx+size/2,top+size/2,size*.8);});ctx.restore();}
async function exportCards(selectedCards=null){const cs=selectedCards||ordered(p());if(!cs.length)return toast('No cards to export');const folder=await chooseExportDirectory();if(folder===null)return;const dims=pixels(p().ratio);for(let i=0;i<cs.length;i++){const c=document.createElement('canvas');[c.width,c.height]=dims;await drawVisual(c,p(),cs[i],{blankWhite:UI.print.blankWhite});drawExportTags(c.getContext('2d'),cs[i],0,0,c.width,c.height,{inset:.022});const blob=await new Promise(r=>c.toBlob(r,'image/png'));await saveBlob(blob,`${String(i+1).padStart(3,'0')} - ${safe(p().name)}.png`,folder);}toast(`${cs.length} cards exported`);}
function dataUrlBytes(url){const bin=atob(url.split(',')[1]);return Uint8Array.from(bin,c=>c.charCodeAt(0));}
function buildPdfFromJpegs(images,landscape){const enc=new TextEncoder(),objects=[];const pages=images.length;let no=3,kids=[];for(let i=0;i<pages;i++){kids.push(`${no} 0 R`);no+=3;}objects[1]=enc.encode('<< /Type /Catalog /Pages 2 0 R >>');objects[2]=enc.encode(`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${pages} >>`);
 no=3;for(const im of images){const pw=landscape?841.89:595.28,ph=landscape?595.28:841.89;objects[no]=enc.encode(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im0 ${no+1} 0 R >> >> /Contents ${no+2} 0 R >>`);const h=enc.encode(`<< /Type /XObject /Subtype /Image /Width ${im.w} /Height ${im.h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${im.bytes.length} >>\nstream\n`),end=enc.encode('\nendstream'),blob=new Uint8Array(h.length+im.bytes.length+end.length);blob.set(h);blob.set(im.bytes,h.length);blob.set(end,h.length+im.bytes.length);objects[no+1]=blob;const body=`q\n${pw} 0 0 ${ph} 0 0 cm\n/Im0 Do\nQ\n`;objects[no+2]=enc.encode(`<< /Length ${enc.encode(body).length} >>\nstream\n${body}endstream`);no+=3;}
 const chunks=[enc.encode('%PDF-1.4\n%\u00e2\u00e3\u00cf\u00d3\n')],offsets=[0];let pos=chunks[0].length;for(let i=1;i<objects.length;i++){offsets[i]=pos;const start=enc.encode(`${i} 0 obj\n`),end=enc.encode('\nendobj\n');chunks.push(start,objects[i],end);pos+=start.length+objects[i].length+end.length;}let xref=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let i=1;i<objects.length;i++)xref+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;xref+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${pos}\n%%EOF`;chunks.push(enc.encode(xref));return new Blob(chunks,{type:'application/pdf'});}
