 const cmp=e.target.closest('[data-complete-chapter]');if(cmp){UI.completionChapterId=cmp.dataset.completeChapter;UI.completionSelected=[];render();return;}const cstat=e.target.closest('[data-completion-status]');if(cstat&&UI.screen==='completion'){completionSetStatus(cstat.dataset.completionStatus,cstat.dataset.cardId);return;}const compcard=e.target.closest('[data-completion-card]');if(compcard&&UI.screen==='completion'){if(performance.now()<(UI.suppressCompletionClickUntil||0))return;completionSelect(compcard.dataset.completionCard,e.metaKey||e.ctrlKey||e.shiftKey,e.shiftKey);return;}
