function onWheel(e){if(UI.screen==='perform'&&e.target.closest('#wave-viewport')){e.preventDefault();if(e.metaKey||e.ctrlKey){UI.performZoom=Math.max(1,Math.min(32,UI.performZoom*(e.deltaY>0?.9:1.1)));drawWave();}else $('#wave-viewport').scrollLeft+=e.deltaY+e.deltaX;}}
files.addEventListener('change',async()=>{const fs=[...files.files],intent=files.dataset.intent;files.value='';try{if(intent==='project'){for(const f of fs){await importProject(f);}render();}else if(intent==='audio'&&fs[0])await importAudio(fs[0]);else if(intent==='thumbnail'&&fs[0]){const project=store.state.projects.find(x=>x.id===files.dataset.id);if(project){const result=await SSImporter.importImageFile(fs[0],project.ratio,{forceSingleImage:true});change('Change project thumbnail',s=>{project.thumbnailId=result.assetId;project.modifiedAt=date();});}}else if(intent==='images'){await importImageFiles(fs,p(),async ids=>change(`Import ${ids.length} drawing(s)`,s=>{const newcards=ids.map(id=>card(UI.chapterId,id));const bucket=files.dataset.destination;if(bucket==='stories')p().stories.push(...newcards);else (p()[bucket]||p().unassigned).push(...newcards);}));}else if(['variant','replace'].includes(intent)){const id=files.dataset.id,s=item(id);if(s&&fs[0])await importImageFiles(fs,p(),async ids=>change('Change variant',state=>{const src=sourceCard(p(),s);if(intent==='replace'){src.variants=[{assetId:ids[0]}];s.blank=false;s.activeVariant=0;}else{src.variants.push({assetId:ids[0]});s.activeVariant=src.variants.length-1;s.blank=false;}}));}}catch(err){console.error(err);toast(err.message);}render();});
app.addEventListener('click',onClick);app.addEventListener('change',onChange);app.addEventListener('input',onInput);app.addEventListener('contextmenu',onContext);app.addEventListener('dragstart',onDragStart);app.addEventListener('dragover',onDragOver);app.addEventListener('dragleave',e=>e.target.closest('.drop-hover')?.classList.remove('drop-hover'));app.addEventListener('drop',onDrop);app.addEventListener('dragend',()=>{cancelChapterDwell();document.body.classList.remove('dragging-chapter','dragging-subchapter');$$('.dragging-source,.drop-before,.drop-after,.drop-onto').forEach(x=>x.classList.remove('dragging-source','drop-before','drop-after'));UI.dragSlot=null;UI.dragPlacement=null;UI.dragHoverChapter=null;$$('.chapter-row').forEach(el=>el.classList.remove('drop-chapter-before','drop-chapter-after','drop-chapter-child'));});app.addEventListener('pointerdown',onWaveResize);app.addEventListener('pointerdown',onLassoDown);
document.addEventListener('click',e=>{if(e.target.closest('.context-pop'))return;$('.context-pop')?.remove();if(e.target.matches('.modal-overlay'))closeModal();else if(e.target.matches('.menu-overlay'))closeMenu();});document.addEventListener('click',e=>{const otherAct=e.target.closest('[data-act]');if(otherAct&&!app.contains(otherAct)){uiSound();actions[otherAct.dataset.act]?.(otherAct);return;}const ctx=e.target.closest('[data-context]');if(ctx&&!app.contains(ctx)){uiSound();chooseContext(ctx.dataset.context);return;}const btn=e.target.closest('[data-modal-btn]');if(btn&&!app.contains(btn)){uiSound();handleModalAction(btn.dataset.modalBtn);return;}const m=e.target.closest('[data-menu-option]');if(m&&!app.contains(m)){uiSound();chooseMenu(+m.dataset.menuOption);return;}const swatch=e.target.closest('[data-folder-hue]');if(swatch&&!app.contains(swatch)){selectFolderColor(swatch);return;}},true);
